#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"typedef struct : public SPROLOZ  {  HWND  hWnd;  float dScale;  bool  bDestroy;  char szName[64];  } Queue_KcaComboBox;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void ClearKcaComboBox(SQueue& q,void* s)  {  Queue_KcaComboBox* p = (Queue_KcaComboBox*)s;  if ( p->bDestroy )    if ( ::IsWindow( p->hWnd ) )      ::DestroyWindow( p->hWnd );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintKcaComboBox(DefinePaint)  {  QueueP(Queue_KcaComboBox);  if (p->dScale != q.setScale)  {	p->dScale = q.setScale;	::PostMessage(p->hWnd,nPressQueue,QUEUE_SCALE,(LPARAM)(&p->dScale));  }  return 0;  }int PressKcaComboBox(DefinePress){  Queue_KcaComboBox* p = (Queue_KcaComboBox*)s;  return 0;}//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddKcaComboBox(DefineTegs)  {  AddQueueEx(Queue_KcaComboBox);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintKcaComboBox;  p->press= &PressKcaComboBox;  p->clear = &ClearKcaComboBox;  Multiline( p->szName, teg[0].value, sizeof(p->szName) );  STegObj obj[] =    {    { 'R', "rect"   , &p->mRect },    { 'E', "rc"     , &p->mRect },    { 'L', "destroy", &p->bDestroy },    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //ASSERT(FALSE);  p->dScale = 1.0;  p->hWnd = (HWND)::SendMsg(def.m_queue.hWnd,QUEUE_COMBO_W,(LPARAM)&p->mRect);  ::PostMessage(p->hWnd,nPressQueue,QUEUE_POINTNAME,(LPARAM)(&p->szName));  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~